struct ReadingModeKey: EnvironmentKey {
    static let defaultValue = "день"
}
extension EnvironmentValues {
    var readingMode: String {
        get { self[ReadingModeKey.self] }
        set { self[ReadingModeKey.self] = newValue }
    }
}
struct ChapterCell: View {
    let title: String
    @Environment(\.readingMode) private var mode
    var body: some View { Text("\(title) · \(mode)") }
}
struct ContentsScreen: View {
    var body: some View {
        VStack {
            ChapterCell(title: "Пролог")
            VStack {
                ChapterCell(title: "Глава 1")
                ChapterCell(title: "Глава 2")
            }
            .environment(\.readingMode, "ночь")
        }
    }
}

«Пролог · день» — до него ключ никто не положил, работает `defaultValue`. «Глава 1 · ночь» и «Глава 2 · ночь» — внутренний `VStack` положил значение для своего поддерева.

