// ReaderSettings — из урока. Без подсказок:
// свой ключ pageMargin (по умолчанию 16);
// QuoteScreen владеет настройками, кладёт их и pageMargin = 20
// в окружение и по кнопке открывает sheet QuoteEditor;
// QuoteEditor читает настройки и pageMargin: поле со шрифтом
// settings.fontSize и отступом pageMargin, «Готово» закрывает.

key:
struct PageMarginKey: EnvironmentKey {
    static let defaultValue = 16.0
}
extension EnvironmentValues {
    var pageMargin: Double {
        get { self[PageMarginKey.self] }
        set { self[PageMarginKey.self] = newValue }
    }
}
struct QuoteScreen: View {
    @State private var settings = ReaderSettings()
    @State private var showsEditor = false
    var body: some View {
        Button("Цитата") { showsEditor = true }
            .sheet(isPresented: $showsEditor) { QuoteEditor() }
            .environment(settings)
            .environment(\.pageMargin, 20)
    }
}
struct QuoteEditor: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(ReaderSettings.self) private var settings
    @Environment(\.pageMargin) private var margin
    @State private var text = ""
    var body: some View {
        VStack {
            TextField("Цитата", text: $text)
                .font(.system(size: settings.fontSize))
                .padding(margin)
            Button("Готово") { dismiss() }
        }
    }
}

`.environment` оборачивает `.sheet`: содержимое sheet получает окружение той точки, где стоит `.sheet`, поэтому модель и поля до редактора доходят. Верно и положить их прямо на содержимое: `QuoteEditor().environment(settings)`. `dismiss` прочитан в самом редакторе.
